from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Return whether the H×W grid can be exactly covered by available tiles.

    Each rectangular tile can be rotated and used at most once. Tiles must be
    aligned to grid cells and fit entirely inside the grid.
    """
    if h <= 0 or w <= 0 or n < 0 or len(tiles) < n:
        return False
    tiles = tiles[:n]
    if any(a <= 0 or b <= 0 for a, b in tiles):
        return False

    full = (1 << (h * w)) - 1
    areas = [a * b for a, b in tiles]

    @lru_cache(maxsize=None)
    def search(occupied: int, remaining: int) -> bool:
        if occupied == full:
            return True

        uncovered = full ^ occupied
        first = (uncovered & -uncovered).bit_length() - 1
        row, col = divmod(first, w)
        blanks = uncovered.bit_count()

        area_sums = {0}
        for i in range(n):
            if remaining & (1 << i):
                area = areas[i]
                area_sums |= {total + area for total in area_sums
                              if total + area <= blanks}
        if blanks not in area_sums:
            return False

        tried_tiles = set()
        for i, (a, b) in enumerate(tiles):
            bit = 1 << i
            if not remaining & bit:
                continue
            shape = tuple(sorted((a, b)))
            if shape in tried_tiles:
                continue
            tried_tiles.add(shape)

            for rh, rw in {(a, b), (b, a)}:
                # Enumerate every placement containing the first uncovered
                # cell; placements overlapping earlier cells are rejected.
                min_r = max(0, row - rh + 1)
                max_r = min(row, h - rh)
                min_c = max(0, col - rw + 1)
                max_c = min(col, w - rw)
                for top in range(min_r, max_r + 1):
                    for left in range(min_c, max_c + 1):
                        mask = 0
                        row_mask = ((1 << rw) - 1) << left
                        for rr in range(top, top + rh):
                            mask |= row_mask << (rr * w)
                        if not (mask & (1 << first)) or occupied & mask:
                            continue
                        if search(occupied | mask, remaining ^ bit):
                            return True
        return False

    return search(0, (1 << n) - 1)

