from typing import List


def max_product_subsequence(nums: List[int], k: int, limit: int) -> int:
    """Find a non-empty subsequence with alternating sum k and maximal product <= limit.

    The alternating sum is the sum at even selected indices minus the sum at odd
    selected indices. The product includes every selected element.
    """
    # The absolute alternating sum cannot exceed the sum of all input values.
    if abs(k) > sum(nums):
        return -1

    # Each state records (alternating_sum, selected_length_parity, product,
    # whether any element has been selected). The parity determines the sign of
    # the next selected value.
    states = {(0, 0, 1, False)}
    for value in nums:
        next_states = set(states)  # omit this input element
        for total, parity, product, nonempty in states:
            new_product = product * value
            if new_product <= limit:
                new_total = total + value if parity == 0 else total - value
                next_states.add((new_total, 1 - parity, new_product, True))
        states = next_states

    answers = (product for total, _, product, nonempty in states
               if total == k and nonempty)
    return max(answers, default=-1)

