from functools import lru_cache


def count_beautiful_numbers(l: int, r: int) -> int:
    """ Count the number of beautiful numbers in the range [l, r] inclusive.

    A positive integer is called beautiful if the product of its digits is
    divisible by the sum of its digits.

    Args:
        l: The lower bound of the range (inclusive)
        r: The upper bound of the range (inclusive)

    Returns:
        The count of beautiful numbers in the range [l, r]
    """

    def count_up_to(bound: int) -> int:
        if bound <= 0:
            return 0

        digits = tuple(map(int, str(bound)))
        total = 0

        # Handle each possible number length separately, so leading zeroes
        # never become part of a number's digit product.
        for length in range(1, len(digits) + 1):
            limit_digits = digits if length == len(digits) else (9,) * length
            max_sum = 9 * length

            for target_sum in range(1, max_sum + 1):
                @lru_cache(maxsize=None)
                def visit(pos: int, digit_sum: int, product_mod: int, tight: bool) -> int:
                    if digit_sum > target_sum or digit_sum + 9 * (length - pos) < target_sum:
                        return 0
                    if pos == length:
                        return int(digit_sum == target_sum and product_mod == 0)

                    low = 1 if pos == 0 else 0
                    high = limit_digits[pos] if tight else 9
                    result = 0
                    for digit in range(low, high + 1):
                        result += visit(
                            pos + 1,
                            digit_sum + digit,
                            (product_mod * digit) % target_sum,
                            tight and digit == high,
                        )
                    return result

                total += visit(0, 0, 1 % target_sum, True)

        return total

    return count_up_to(r) - count_up_to(l - 1)

