from typing import List, Tuple
from functools import lru_cache


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise
    """
    if h <= 0 or w <= 0 or h > 10 or w > 10:
        return False
    count = min(n, len(tiles))
    tiles = tiles[:count]
    full = (1 << (h * w)) - 1
    area = h * w
    sizes = [a * b for a, b in tiles]

    # Search subsets whose total area exactly matches the board.
    subsets = []
    for chosen in range(1 << count):
        if sum(sizes[i] for i in range(count) if chosen >> i & 1) == area:
            subsets.append(chosen)
    if not subsets:
        return False

    # Each rectangle placement is represented by its occupied cells.
    placements = []
    for a, b in tiles:
        opts = {(a, b), (b, a)}
        by_shape = []
        for rh, rw in opts:
            if rh > h or rw > w:
                continue
            for r in range(h - rh + 1):
                for c in range(w - rw + 1):
                    mask = 0
                    for rr in range(r, r + rh):
                        rowbits = ((1 << rw) - 1) << (rr * w + c)
                        mask |= rowbits
                    by_shape.append(mask)
        placements.append(tuple(set(by_shape)))

    for selected in subsets:
        @lru_cache(None)
        def search(occupied: int, remaining: int) -> bool:
            if occupied == full:
                return True
            # Force the first uncovered cell; any tile covering it must begin there,
            # since all earlier cells are already occupied.
            bit = next(i for i in range(area) if not (occupied >> i) & 1)
            r, c = divmod(bit, w)
            anchor = 1 << bit
            m = remaining
            while m:
                tile_bit = m & -m
                i = tile_bit.bit_length() - 1
                m -= tile_bit
                if not (selected >> i) & 1:
                    continue
                a, b = tiles[i]
                for rh, rw in {(a, b), (b, a)}:
                    if r + rh > h or c + rw > w:
                        continue
                    mask = 0
                    for rr in range(r, r + rh):
                        mask |= ((1 << rw) - 1) << (rr * w + c)
                    if mask & anchor and not (mask & occupied):
                        if search(occupied | mask, remaining ^ tile_bit):
                            return True
            return False

        if search(0, selected):
            return True
    return False

