def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    """Count integers in the inclusive range whose digit sum is within bounds."""
    mod = 1_000_000_007

    def count_at_most(bound: str, limit: int) -> int:
        if limit < 0:
            return 0
        dp = [0] * (limit + 1)  # prefixes already smaller than the bound
        tight_sum = 0
        for ch in bound:
            digit = ord(ch) - ord("0")
            nxt = [0] * (limit + 1)
            for total, ways in enumerate(dp):
                if ways:
                    for d in range(min(9, limit - total) + 1):
                        nxt[total + d] = (nxt[total + d] + ways) % mod
            for d in range(min(digit, limit - tight_sum + 1)):
                total = tight_sum + d
                if total <= limit:
                    nxt[total] = (nxt[total] + 1) % mod
            tight_sum += digit
            dp = nxt
        answer = sum(dp) % mod
        if tight_sum <= limit:
            answer = (answer + 1) % mod
        return answer

    def decrement(value: str) -> str | None:
        digits = list(value)
        i = len(digits) - 1
        while i >= 0 and digits[i] == "0":
            digits[i] = "9"
            i -= 1
        if i < 0:
            return None
        digits[i] = str(int(digits[i]) - 1)
        return "".join(digits).lstrip("0") or "0"

    def count_range(upper: str, lower: str) -> int:
        below = decrement(lower)
        result = count_at_most(upper, max_sum) - count_at_most(upper, min_sum - 1)
        if below is not None:
            result -= count_at_most(below, max_sum) - count_at_most(below, min_sum - 1)
        return result % mod

    return count_range(num2, num1)

