def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Count proper 3-colorings of the grid consistent with its fixed cells."""
    if W > H:
        rows = [tuple(grid[r][c] for r in range(H)) for c in range(W)]
    else:
        rows = [tuple(row) for row in grid]

    width = len(rows[0])

    def states_for(fixed):
        states = []
        state = []

        def build(col):
            if col == width:
                states.append(tuple(state))
                return
            choices = (ord(fixed[col]) - 48,) if fixed[col] != "?" else (1, 2, 3)
            for color in choices:
                if col == 0 or color != state[-1]:
                    state.append(color)
                    build(col + 1)
                    state.pop()

        build(0)
        return states

    dp = {state: 1 for state in states_for(rows[0])}
    if not dp:
        return 0

    for fixed in rows[1:]:
        next_dp = {}
        for above, ways in dp.items():
            below = []

            def build(col):
                if col == width:
                    state = tuple(below)
                    next_dp[state] = (next_dp.get(state, 0) + ways) % MOD
                    return
                choices = (ord(fixed[col]) - 48,) if fixed[col] != "?" else (1, 2, 3)
                for color in choices:
                    if color == above[col]:
                        continue
                    if col and color == below[-1]:
                        continue
                    below.append(color)
                    build(col + 1)
                    below.pop()

            build(0)
        dp = next_dp
        if not dp:
            return 0

    return sum(dp.values()) % MOD

