from math import comb

MOD = 998244353


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count words whose only missing length-M subsequence is X."""
    code = 0
    for value in X:
        if not 1 <= value <= K:
            return 0
        code = code * K + value - 1

    required = K ** M - 1
    # A word has at most C(N,M) distinct subsequences of length M.
    if comb(N, M) < required:
        return 0

    # Every constant word other than X must occur.
    if len(set(X)) != 1 and N < K * M:
        return 0
    if len(set(X)) == 1 and N < (K - 1) * M:
        return 0

    # Each layer is a bitset of distinct subsequences of that length,
    # encoded as base-K integers. Merge prefixes with identical layers.
    initial = (0,) * (M + 1)
    states = {initial: 1}
    target = 1 << code

    for used in range(N):
        remaining = N - used - 1
        nxt = {}
        for layers, ways in states.items():
            for symbol in range(K):
                updated = list(layers)
                for length in range(min(M, used + 1), 0, -1):
                    if length == 1:
                        additions = 1 << symbol
                    else:
                        prefixes = layers[length - 1]
                        additions = 0
                        while prefixes:
                            bit = prefixes & -prefixes
                            prefix_code = bit.bit_length() - 1
                            additions |= 1 << (prefix_code * K + symbol)
                            prefixes -= bit
                    updated[length] |= additions

                state = tuple(updated)
                if state[M] & target:
                    continue
                missing = K ** M - state[M].bit_count()
                if remaining * (K ** (M - 1)) < missing - 1:
                    continue
                nxt[state] = (nxt.get(state, 0) + ways) % MOD
        states = nxt
        if not states:
            return 0

    target_mask = 1 << code
    full_mask = (1 << (K ** M)) - 1
    return sum(
        ways for layers, ways in states.items()
        if (full_mask ^ layers[M]) == target_mask
    ) % MOD

