MOD = 998244353


def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Count proper 3-colorings of the grid consistent with its fixed cells."""
    # Work across the shorter dimension so the row-state frontier stays small.
    if W <= H:
        rows = [tuple(row) for row in grid]
    else:
        rows = [tuple(grid[r][c] for r in range(H)) for c in range(W)]

    width = len(rows[0])

    def row_states(fixed):
        result = []

        def build(col, state):
            if col == width:
                result.append(tuple(state))
                return
            choices = (int(fixed[col]),) if fixed[col] != "?" else (1, 2, 3)
            for value in choices:
                if col == 0 or value != state[-1]:
                    state.append(value)
                    build(col + 1, state)
                    state.pop()

        build(0, [])
        return result

    dp = {state: 1 for state in row_states(rows[0])}
    if not dp:
        return 0

    # Cache transition lists by source state and destination row clues.
    transition_cache = {}
    for fixed in rows[1:]:
        next_dp = {}
        for source, count in dp.items():
            key = (source, fixed)
            targets = transition_cache.get(key)
            if targets is None:
                found = []
                out = []

                def build(col):
                    if col == width:
                        found.append(tuple(out))
                        return
                    choices = (int(fixed[col]),) if fixed[col] != "?" else (1, 2, 3)
                    for value in choices:
                        if value == source[col]:
                            continue
                        if col and value == out[-1]:
                            continue
                        out.append(value)
                        build(col + 1)
                        out.pop()

                build(0)
                targets = tuple(found)
                transition_cache[key] = targets
            for target in targets:
                next_dp[target] = (next_dp.get(target, 0) + count) % MOD
        dp = next_dp
        if not dp:
            return 0
    return sum(dp.values()) % MOD

