from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Return the minimum adjacency moves between the tiles containing the given points."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def get_k(i, j, x, y):
        return y - j * K if (i - j) % 2 == 0 else x - i * K

    sk, tk = get_k(si, sj, S_x, S_y), get_k(ti, tj, T_x, T_y)
    width, height = abs(ti - si) + 1, abs(tj - sj) + 1
    if width * height > 10000:
        return abs(ti - si) + abs(tj - sj)

    pad = 10
    imin, imax = min(si, ti) - pad, max(si, ti) + pad
    jmin, jmax = min(sj, tj) - pad, max(sj, tj) + pad
    vals = {}
    for i in range(imin, imax + 1):
        for j in range(jmin, jmax + 1):
            ks = {0, K - 1}
            if (i, j) == (si, sj):
                ks.add(sk)
            if (i, j) == (ti, tj):
                ks.add(tk)
            vals[i, j] = sorted(ks)

    ids, coords = {}, []
    for (i, j), ks in vals.items():
        for k in ks:
            ids[i, j, k] = len(coords)
            coords.append((i, j, k))
    graph = [[] for _ in coords]

    def link(a, b, cost=1):
        u, v = ids[a], ids[b]
        graph[u].append((v, cost))
        graph[v].append((u, cost))

    for (i, j), ks in vals.items():
        for p, k in enumerate(ks):
            for z in ks[p + 1:]:
                link((i, j, k), (i, j, z), z - k)

    for i in range(imin, imax + 1):
        for j in range(jmin, jmax + 1):
            ah = (i - j) % 2 == 0
            if i < imax:
                if ah:
                    for k in vals[i, j]:
                        link((i, j, k), (i + 1, j, 0))
                else:
                    for k in vals[i + 1, j]:
                        link((i, j, K - 1), (i + 1, j, k))
            if j < jmax:
                if ah:
                    for k in vals[i, j + 1]:
                        link((i, j, K - 1), (i, j + 1, k))
                else:
                    for k in vals[i, j]:
                        link((i, j, k), (i, j + 1, 0))

    start, goal = ids[si, sj, sk], ids[ti, tj, tk]
    dist = [None] * len(coords)
    dist[start] = 0
    heap = [(0, start)]
    while heap:
        d, u = heappop(heap)
        if d != dist[u]:
            continue
        if u == goal:
            return d
        for v, c in graph[u]:
            nd = d + c
            if dist[v] is None or nd < dist[v]:
                dist[v] = nd
                heappush(heap, (nd, v))
    return dist[goal]

