def count_good_sequences(N: int, M: int) -> int:
    """Count length-M sequences whose product is at most N and has sigma(n) divisible by 3."""
    MOD = 998244353
    if N < 1 or M < 1:
        return 0

    # For n = product(p**e), the number of ordered length-M factorizations is
    # prod C(M+e-1, e).  Also sigma is multiplicative. Modulo 3 its prime
    # power factor is zero precisely for p == 2 (mod 3), e odd, or
    # p == 1 (mod 3), e == 2 (mod 3).
    limit = int(N ** 0.5)
    sieve = bytearray(b"\x01") * (limit + 1)
    if limit >= 0:
        sieve[0] = 0
    if limit >= 1:
        sieve[1] = 0
    for p in range(2, int(limit ** 0.5) + 1):
        if sieve[p]:
            start = p * p
            sieve[start:limit + 1:p] = b"\x00" * (((limit - start) // p) + 1)
    primes = [p for p in range(2, limit + 1) if sieve[p]]

    max_exp = N.bit_length()
    inv = [0] * (max_exp + 1)
    for e in range(1, max_exp + 1):
        inv[e] = pow(e, MOD - 2, MOD)
    # C(M+e-1,e), for the small exponents possible under the bound.
    choose = [1] * (max_exp + 1)
    for e in range(1, max_exp + 1):
        choose[e] = choose[e - 1] * (M + e - 1) % MOD * inv[e] % MOD

    block_size = 100_000
    answer = 0
    for lo in range(1, N + 1, block_size):
        hi = min(N + 1, lo + block_size)
        rem = list(range(lo, hi))
        weights = [1] * (hi - lo)
        good = bytearray(b"\x00") * (hi - lo)
        for p in primes:
            if p * p >= hi:
                break
            first = ((lo + p - 1) // p) * p
            for x in range(first, hi, p):
                idx = x - lo
                e = 0
                while rem[idx] % p == 0:
                    rem[idx] //= p
                    e += 1
                if e:
                    weights[idx] = weights[idx] * choose[e] % MOD
                    if (p % 3 == 2 and e % 2 == 1) or (p % 3 == 1 and e % 3 == 2):
                        good[idx] = 1

        for idx, q in enumerate(rem):
            if q > 1:
                weights[idx] = weights[idx] * choose[1] % MOD
                if q % 3 == 2:
                    good[idx] = 1
        for idx, is_good in enumerate(good):
            if is_good:
                answer += weights[idx]
        answer %= MOD
    return answer

